// check-manifests: every file a TOC/XML manifest loads must exist, with the
// same letter case as on disk (Linux CI is case-sensitive; WoW is not), and
// no file may load twice.
//
// Primary manifest: Wayfinder.toc (generated by tools/build-toc) for game type
// camelot, the TOC we ship. Upstream's TOCs (RXPGuides*.toc) are still checked
// for every game type, for information: their findings are compared with
// baseline.json so an upstream sync that changes them is noticed.
//
//   npm run check:manifests                       check against baseline.json
//   npm run check:manifests -- --write-baseline   accept the current findings (keeps reasons)
//   npm run check:manifests -- --list             print Wayfinder.toc's load order
//   npm run check:manifests -- --list camelot     print upstream's load order for a game type
//
// Gate (exit 0): every Wayfinder.toc finding and every upstream finding is in
// the baseline, and no baseline entry is stale. Exit 1 otherwise.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { loadConfig } from "../build-toc/index.ts";
import { addonNames, FileIndex, GAME_TYPES, loadOrder, type Finding, type GameType, type LoadResult } from "./manifest.ts";

export { loadOrder, loadOrderByGameType, GAME_TYPES } from "./manifest.ts";
export type { GameType, LoadedFile, LoadResult, Finding } from "./manifest.ts";

const REPO_ROOT = resolve(fileURLToPath(new URL("../..", import.meta.url)));
const BASELINE = fileURLToPath(new URL("./baseline.json", import.meta.url));
const DEFAULT_ADDON = "RXPGuides";

export interface BaselineEntry {
  /** TOC base name; entries without one predate Wayfinder.toc and mean RXPGuides. */
  addon?: string;
  gameType: GameType;
  kind: Finding["kind"];
  from: string;
  ref: string;
  note?: string;
  /** Why the finding is accepted (required for entries we add by hand). */
  reason?: string;
}

/** Baseline key ignores line numbers so unrelated edits don't invalidate it. */
export function findingKey(f: { addon?: string; gameType: string; kind: string; from: string; ref: string }): string {
  return `${f.addon ?? DEFAULT_ADDON}|${f.gameType}|${f.kind}|${f.from}|${f.ref}`;
}

export function compareToBaseline(findings: Finding[], baseline: BaselineEntry[]): { fresh: Finding[]; stale: BaselineEntry[] } {
  const base = new Set(baseline.map(findingKey));
  const seen = new Set(findings.map(findingKey));
  return {
    fresh: findings.filter((f) => !base.has(findingKey(f))),
    stale: baseline.filter((b) => !seen.has(findingKey(b))),
  };
}

export interface Analysis {
  /** Wayfinder.toc for its game type; null when the file does not exist. */
  primary: LoadResult | null;
  primaryToc: string;
  /** Upstream addons (every TOC base name except ours) for every game type. */
  upstream: LoadResult[];
}

export function analyze(root: string, primary: { addon: string; gameType: GameType; output: string }): Analysis {
  const index = FileIndex.fromDisk(root);
  const upstream: LoadResult[] = [];
  for (const addon of addonNames(index)) {
    if (addon.toLowerCase() === primary.addon.toLowerCase()) continue;
    for (const g of GAME_TYPES) upstream.push(loadOrder(g, { root, index, addon }));
  }
  const exists = index.find(primary.output) !== undefined;
  return {
    primary: exists ? loadOrder(primary.gameType, { root, index, addon: primary.addon }) : null,
    primaryToc: primary.output,
    upstream,
  };
}

function fmt(f: Finding): string {
  return `  ${f.kind.padEnd(9)} ${f.from}${f.line ? ":" + f.line : ""}  "${f.ref}"  ${f.detail}`;
}

function summary(r: LoadResult): string {
  const lua = r.files.filter((f) => f.kind === "lua" && f.exists).length;
  const xml = r.files.filter((f) => f.kind === "xml" && f.exists).length;
  const rootRel = r.files.filter((f) => f.via === "addon-root").length;
  return `TOC ${r.toc ?? "none"}; loads ${lua} Lua and ${xml} XML files; ${rootRel} XML references resolved against the addon root (fallback rule).`;
}

function printList(r: LoadResult): void {
  for (const f of r.files) console.log(`${f.exists ? " " : "!"} ${f.kind.padEnd(4)} ${f.path}${f.via && f.via !== "toc" ? `  (${f.via})` : ""}`);
}

function main(argv: string[]): number {
  const root = REPO_ROOT;
  const cfg = loadConfig();
  const a = analyze(root, cfg);

  const listIdx = argv.indexOf("--list");
  if (listIdx >= 0) {
    const arg = argv[listIdx + 1];
    if (!arg || arg.toLowerCase() === cfg.addon.toLowerCase()) {
      if (!a.primary) throw new Error(`${a.primaryToc} not found; run "npm run build:toc"`);
      printList(a.primary);
    } else for (const r of a.upstream.filter((x) => x.gameType === arg)) printList(r);
    return 0;
  }

  const findings = [...(a.primary?.findings ?? []), ...a.upstream.flatMap((r) => r.findings)];
  const baseline: BaselineEntry[] = existsSync(BASELINE) ? JSON.parse(readFileSync(BASELINE, "utf8")).findings : [];

  if (argv.includes("--write-baseline")) {
    const old = new Map(baseline.map((b) => [findingKey(b), b]));
    const unique = new Map<string, BaselineEntry>();
    for (const f of findings) {
      const key = findingKey(f);
      const reason = old.get(key)?.reason;
      unique.set(key, {
        ...(f.addon && f.addon !== DEFAULT_ADDON ? { addon: f.addon } : {}),
        gameType: f.gameType,
        kind: f.kind,
        from: f.from,
        ref: f.ref,
        note: f.detail,
        ...(reason ? { reason } : {}),
      });
    }
    writeFileSync(
      BASELINE,
      JSON.stringify(
        {
          description:
            "Known manifest findings. Entries without 'addon' are upstream's RXPGuides TOCs (from RXPGuides 22e6ce26 plus the deletions recorded with a 'reason'); 'addon: Wayfinder' entries are for our generated Wayfinder.toc and are inherited from upstream XML we do not edit. New or vanished findings fail the check.",
          findings: [...unique.values()],
        },
        null,
        2,
      ) + "\n",
    );
    console.log(`wrote ${unique.size} baseline entries to ${BASELINE}`);
    return 0;
  }

  let failed = false;

  // Primary: Wayfinder.toc.
  if (!a.primary) {
    console.error(`FAIL: ${a.primaryToc} not found. Run "npm run build:toc".`);
    failed = true;
  } else {
    const p = a.primary;
    const byKind = (k: Finding["kind"]) => p.findings.filter((f) => f.kind === k).length;
    console.log(`[${cfg.addon} ${cfg.gameType}] PRIMARY ${summary(p)}`);
    console.log(`  findings: missing=${byKind("missing")} case=${byKind("case")} duplicate=${byKind("duplicate")} other=${p.findings.length - byKind("missing") - byKind("case") - byKind("duplicate")}`);
    for (const f of p.findings) console.log(fmt(f));
  }

  // Upstream TOCs: information, compared with the baseline.
  console.log(`\nUpstream TOCs (informational; gated only on change from baseline):`);
  for (const r of a.upstream) {
    const byKind = (k: Finding["kind"]) => r.findings.filter((f) => f.kind === k).length;
    const files = r.files.filter((f) => f.kind === "lua" || f.kind === "xml");
    console.log(
      `  [${r.addon} ${r.gameType}] toc=${r.toc ?? "(none: addon not loaded)"} files=${files.length} missing=${byKind("missing")} case=${byKind("case")} duplicate=${byKind("duplicate")} other=${r.findings.length - byKind("missing") - byKind("case") - byKind("duplicate")}`,
    );
  }
  for (const r of a.upstream.filter((x) => x.gameType === cfg.gameType)) console.log(`  upstream ${r.gameType}: ${summary(r)}`);

  const unexplained = baseline.filter((b) => b.addon && b.addon !== DEFAULT_ADDON && !b.reason?.trim());
  if (unexplained.length) {
    console.error(`\nFAIL: baseline entries for ${cfg.output} must carry a "reason":`);
    for (const b of unexplained) console.error(`  ${findingKey(b)}`);
    failed = true;
  }

  const { fresh, stale } = compareToBaseline(findings, baseline);
  if (stale.length) {
    console.error(`\nFAIL: ${stale.length} baseline entr${stale.length === 1 ? "y is" : "ies are"} no longer found (fixed upstream?). Check, then run with --write-baseline:`);
    for (const s of stale) console.error(`  ${findingKey(s)}`);
    failed = true;
  }
  if (fresh.length) {
    console.error(`\nFAIL: ${fresh.length} new finding(s) not in baseline:`);
    for (const f of fresh) console.error(`  [${f.addon ?? DEFAULT_ADDON} ${f.gameType}]${fmt(f)}`);
    failed = true;
  }
  if (failed) return 1;
  console.log(`\nOK: ${a.primaryToc} has no findings outside the baseline; upstream findings unchanged (${findings.length} finding(s), ${baseline.length} baseline entries).`);
  return 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (e) {
    console.error(`check-manifests: ${(e as Error).stack ?? e}`);
    process.exitCode = 1;
  }
}
